        correct: 2,
        explanation: "(VND660 million + VND330 million) * 10% = VND99 million\nThe non-registered promotion to customers, and goods given to employees, are both subject to value added tax (VAT). \n“Nghị định 181/2025/NĐ-CP\nĐiều 6. Giá tính thuế đối với hàng hóa, dịch vụ dùng để trao đổi, tiêu dùng nội bộ, biếu, tặng, cho và hàng hóa, dịch vụ dùng để khuyến mại \n1. Đối với hàng hóa, dịch vụ dùng để trao đổi, tiêu dùng nội bộ, biếu, tặng, cho là giá tính thuế giá trị gia tăng của hàng hóa, dịch vụ cùng loại hoặc tương đương tại thời điểm phát sinh các hoạt động này \n2. Đối với hàng hóa, dịch vụ dùng để khuyến mại theo quy định của pháp luật về thương mại, giá tính thuế được xác định bằng không (0), trừ trường hợp bán hàng, cung cấp dịch vụ với giá thấp hơn giá bán hàng, cung cấp dịch vụ trước đó, được áp dụng trong thời gian khuyến mại (khuyến mại bằng hình thức giảm giá) thì giá tính thuế là giá bán đã giảm áp dụng trong thời gian khuyến mại đã đăng ký hoặc thông báo theo quy định của pháp luật thương mại về hoạt động xúc tiến thương mại.\nTrường hợp bán hàng hóa, cung cấp dịch vụ quy định tại khoản này nhưng không thực hiện theo quy định về khuyến mại của pháp luật về thương mại thì giá tính thuế thực hiện như hàng hóa biếu, tặng, cho quy định tại khoản 1 Điều này.”"
