        question: "RLS Co is a Vietnamese company headquartered in Ho Chi Minh City.\nIn the year 2025, RLS Co conducted some real estate transfer transactions in Dong Nai and Binh Duong provinces.\n<b>Which of the following are the correct statements about RLS Co's corporate income tax declaration requirements in Vietnam with regard to the real estate transfers?</b>\n(1) RLS Co is required to provisionally declare AND pay tax on a quarterly basis to Dong Nai and Binh Duong provinces.\n(2) At the year-end, RLS Co is required to determine the corporate income tax payable to Dong Nai and Binh Duong from the real estate transfers in each province.\n(3) At the year-end, RLS Co is required to declare and finalise tax from real estate transfers with Ho Chi Minh City tax authority.",
        options: [
            "1 and 3 only",
            "1, 2 and 3",
            "1 and 2 only",
            "2 and 3 only"
        ],
        correct: 3,
        explanation: "RLS Co is required to pay (not declare) provisional tax to each province on a quarterly basis. At the year end, RLS Co has to determine the corporate income tax payable to Dong Nai and Binh Duong from the real estate transfers in each province and offset with the tax provisionally paid. RLS Co is also required to finalise tax from real estate transfers with the tax authorities in the headquarter (Ho Chi Minh City). \n“Điều 17. Khai thuế, tính thuế, quyết toán thuế, phân bổ và nộp thuế thu nhập doanh nghiệp\nb) Đối với hoạt động chuyển nhượng bất động sản:\nb.1) Khai thuế, tạm nộp thuế hàng quý: Người nộp thuế không phải nộp hồ sơ khai thuế quý nhưng phải xác định số thuế tạm nộp hàng quý theo quy định tại điểm b khoản 2 Điều này để nộp tiền thuế thu nhập doanh nghiệp vào ngân sách nhà nước cho từng tỉnh nơi có hoạt động chuyển nhượng bất động sản.\nb.2) Quyết toán thuế: Người nộp thuế khai quyết toán thuế thu nhập doanh nghiệp đối với toàn bộ hoạt động chuyển nhượng bất động sản theo mẫu số 03/TNDN, xác định số thuế thu nhập doanh nghiệp phải nộp cho từng tỉnh theo quy định tại điểm b khoản 2 Điều này tại phụ lục bảng phân bổ số thuế thu nhập doanh nghiệp phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động chuyển nhượng bất động theo mẫu số 03-8A/TNDN ban hành kèm theo phụ lục II Thông tư này cho cơ quan thuế quản lý trực tiếp; nộp tiền vào ngân sách nhà nước cho từng tỉnh nơi có hoạt động chuyển nhượng bất động sản theo quy định tại khoản 4 Điều 12 Thông tư này.\nSố thuế đã tạm nộp trong năm tại các tỉnh (không bao gồm số thuế đã tạm nộp cho doanh thu thực hiện dự án đầu tư cơ sở hạ tầng, nhà để chuyển nhượng hoặc cho thuê mua, có thu tiền ứng trước của khách hàng theo tiến độ mà doanh thu này chưa được tính vào doanh thu tính thuế thu nhập doanh nghiệp trong năm) được trừ vào với số thuế thu nhập doanh nghiệp phải nộp từ hoạt động chuyển nhượng bất động sản của từng tỉnh trên mẫu số 03 232 8A/TNDN ban hành kèm theo phụ lục II Thông tư này, nếu chưa trừ hết thì tiếp tục trừ vào số thuế thu nhập doanh nghiệp phải nộp từ hoạt động chuyển nhượng bất động sản theo quyết toán tại trụ sở chính trên mẫu số 03/TNDN ban hành kèm theo phụ lục II Thông tư này.\nTrường hợp số thuế đã tạm nộp theo quý nhỏ hơn số thuế phải nộp theo quyết toán thuế trên tờ khai quyết toán tại trụ sở chính trên mẫu số 03/TNDN ban hành kèm theo phụ lục II Thông tư này thì người nộp thuế phải nộp số thuế còn thiếu cho địa phương nơi đóng trụ sở chính. Trường hợp số thuế đã tạm nộp theo quý lớn hơn số thuế phải nộp theo quyết toán thuế thì được xác định là số thuế nộp thừa và xử lý theo quy định tại Điều 60 Luật Quản lý thuế và Điều 25 Thông tư này.”"
