        question: "BDC JSC is a Vietnamese company listed on the stock market. The company has seven board members; three are active members and the remaining four are non-active members.\nAccording to the board resolution, members in each category should receive equal salary. Active members who participate directly in managing the company's operations receive a salary which is 200% of the salary received by non-active members. The company recorded a total salary expense for the board of VND 10,000 million in its accounting books for the fiscal year ended 31 December 2025.\n<b>What are the non-deductible expenses BDC JSC should declare in its corporate income tax (CIT) return for the fiscal year ended 31 December 2025?</b>",
