        type: "standard",
        question: "MZ Co is a Singaporean company with no presence in Vietnam. In late 2023, MZ Co entered into an agreement to sell luxury watches in the Vietnamese market via its exclusive distributor, AG Co. MZ Co would determine the price of the watches depending on international trends and market conditions.\nIn the year 2025, the revenue from the sales of MZ Co's watches by AG Co in the Vietnamese market amounted to VND50,000 million.\nDuring the year 2025, AG Co also advanced an amount equivalent to VND2,000 million for advertising in Vietnam, which was duly reimbursed by MZ Co in the same year.\n<b>What is the corporate income tax portion of the foreign contractor tax (FCT) liability that AG Co should declare on its FCT return in the year 2025 for the above transactions, assuming the contract is silent on which party would bear the withholding tax?</b>",
        options: [
            "VND520 million",
            "VND0",
            "VND480 million",
            "VND500 million"
        ],
        correct: 3,
        explanation: "VND50,000 million * 1% = VND500 million\nAccording to Example 2 of Circular 103/2014, as MZ Co can determine the selling price, it would be subject to foreign contractor tax (FCT) for the revenue from sales of watches in Vietnam. The CIT rate is 1%. As the contract is silent on withholding tax, it would be gross of tax. Advertising costs were advanced and repaid in the same year, and hence would not be subject to FCT. \nĐiều 1. Đối tượng áp dụng  \n3. Tổ chức, cá nhân nước ngoài thực hiện một phần hoặc toàn bộ hoạt động kinh doanh phân phối hàng hóa, cung cấp dịch vụ tại Việt Nam trong đó tổ chức, cá nhân nước ngoài vẫn là chủ sở hữu đối với hàng hóa giao cho tổ chức Việt Nam hoặc chịu trách nhiệm về chi phí phân phối, quảng cáo, tiếp thị, chất lượng dịch vụ, chất lượng hàng hóa giao cho tổ chức Việt Nam hoặc ấn định giá bán hàng hóa hoặc giá cung ứng dịch vụ; bao gồm cả trường hợp uỷ quyền hoặc thuê một số tổ chức Việt Nam thực hiện một phần dịch vụ phân phối, dịch vụ khác liên quan đến việc bán hàng hóa tại Việt Nam.\nVí dụ 2:\nDoanh nghiệp A ở nước ngoài giao hàng hóa hoặc uỷ quyền thực hiện một số dịch vụ liên quan (như vận chuyển, phân phối, tiếp thị, quảng cáo...) cho Doanh nghiệp Việt Nam B trong đó Doanh nghiệp A là chủ sở hữu đối với hàng hóa giao cho Doanh nghiệp B hoặc Doanh nghiệp A chịu trách nhiệm về chi phí, chất lượng dịch vụ, chất lượng hàng hóa giao cho Doanh nghiệp B hoặc Doanh nghiệp A ấn định giá bán hàng hóa hoặc giá cung ứng dịch vụ thì Doanh nghiệp A là đối tượng áp dụng theo quy định tại Thông tư này.”"
