        question: "26. VNT Co is a Vietnamese company acting as an agent for XLS Co, a Singapore-based maritime transportation company. In 2025, XLS Co instructed VNT Co to hire a Vietnamese vessel for VND470 million to transport cargo from XLS Co's client in Vietnam to Singapore. The cargo was transhipped in Singapore and then transported to Brazil in XLS Co's own vessels. The gross freight for transportation from Vietnam to Brazil, agreed with XLS Co's Vietnamese client, is USD180,000.\n<b>What is the corporate income tax portion of foreign contractor tax (in VND millions equivalent) which XLS Co is subject to in relation to the above transportation activity?</b>",
