        explanation: "Corporate Income tax (CIT): USD 14,250 ((300,000 – 15,000) * 5%)\nValue added tax (VAT): USD 15,000 (1.3 million – 1 million) * 5%.\nAccording to Circular 103/2014, when a foreign contractor subcontracts all provision of supplies and only provides services, the tax rates for services (5% VAT and 5% CIT) will apply. As the contract is gross of CIT and VAT, VAT should be calculated first. \n“Điều 12. Thuế giá trị gia tăng \n1. Doanh thu tính thuế GTGT b) Xác định tỷ lệ % để tính thuế GTGT trên doanh thu đối với một số trường hợp cụ thể: b.1) Riêng đối với hoạt động xây dựng, lắp đặt có bao thầu nguyên vật liệu hoặc máy móc, thiết bị đi kèm công trình xây dựng: Trường hợp hợp đồng nhà thầu tách riêng được giá trị từng hoạt động kinh doanh thì Nhà thầu nước ngoài không phải nộp thuế GTGT trên giá trị nguyên vật liệu hoặc máy móc, thiết bị đã nộp thuế GTGT ở khâu nhập khẩu hoặc thuộc diện không chịu thuế GTGT; đối với từng phần giá trị công việc còn lại theo hợp đồng thì áp dụng tỷ lệ % để tính thuế GTGT trên doanh thu tương ứng với hoạt động kinh doanh đó. Trường hợp hợp đồng nhà thầu không tách riêng được giá trị từng hoạt động kinh doanh thì áp dụng tỷ lệ % để tính thuế GTGT trên doanh thu là 3% tính trên toàn bộ giá trị hợp đồng (bao gồm cả giá trị nguyên vật liệu hoặc máy móc, thiết bị nhập khẩu). Trường hợp Nhà thầu nước ngoài ký hợp đồng với các Nhà thầu phụ để giao lại toàn bộ các phần giá trị công việc hoặc hạng mục có bao thầu nguyên vật liệu hoặc máy móc, thiết bị, Nhà thầu nước ngoài chỉ thực hiện phần giá trị dịch vụ còn lại theo hợp đồng nhà thầu thì tỷ lệ % để tính thuế GTGT được áp dụng đối với ngành nghề dịch vụ (5%). Điều \n13. Thuế thu nhập doanh nghiệp \n1. Doanh thu tính thuế TNDN b) Tỷ lệ (%) thuế TNDN tính trên doanh thu tính thuế đối với một số trường hợp cụ thể: b.1) Riêng đối với hoạt động xây dựng, lắp đặt có bao thầu nguyên vật liệu hoặc máy móc, thiết bị đi kèm công trình xây dựng: Trường hợp hợp đồng nhà thầu tách riêng giá trị từng hoạt động kinh doanh thì từng phần giá trị công việc theo hợp đồng được áp dụng tỷ lệ % thuế TNDN trên doanh thu tương ứng với hoạt động kinh doanh đó. Trường hợp hợp đồng nhà thầu không tách riêng giá trị từng hoạt động kinh doanh thì thì tỷ lệ % thuế TNDN tính trên doanh thu tính thuế là 2% trên toàn bộ giá trị hợp đồng. Trường hợp Nhà thầu nước ngoài ký hợp đồng với các Nhà thầu phụ để giao lại toàn bộ các phần giá trị công việc hoặc hạng mục có bao thầu nguyên vật liệu hoặc máy móc, thiết bị, Nhà thầu nước ngoài chỉ 258 thực hiện phần giá trị dịch vụ còn lại theo hợp đồng nhà thầu thì tỷ lệ % thuế TNDN tính trên doanh thu tính thuế TNDN được áp dụng đối với ngành nghề dịch vụ (5%)."
