        id: 179,
        section: "Part D",
        type: "standard",
        question: "30. VXN EXD Co is a Singapore-based company providing express delivery services. The company entered into a contract with AGD Co, a Vietnamese company, for AGD Co to act as the exclusive agent of EXD Co in Vietnam. AGD Co bears all foreign contractor tax (FCT) in Vietnam under the contract. In 2025, AGD Co remitted fees of USD900,000 to EXD Co for services to Vietnamese clients. Of this amount, 40% related to shipping from overseas to Vietnam, and the remaining balance was for shipping from Vietnam to overseas. The activities of EXD Co are treated as ‘services' for FCT purposes.\n<b>What is the corporate income tax (CIT) portion of the FCT which AGD Co should declare in its FCT return in 2025 in respect of the contract with EXD Co?</b>",
