        question: "34. In 2025, MHT Co, a Japanese company, signed a contract to supply and install equipment for PCR Co, a Vietnamese company. The contract price was USD2 million gross of value added tax (VAT) and corporate income tax (CIT). MHT Co purchased goods relating to this contract, valued at USD0.50 million, from Vietnamese suppliers.\n<b>What is the amount (in USD) of the corporate income tax (CIT) portion of foreign contractor tax (FCT) which PCR Co would be required to withhold on the above contract with MHT Co, assuming MHT Co applied the deemed method for FCT declaration?</b>",
