        correct: 1,
        explanation: "USD10,000 (500,000*2%)\nAccording to Article 13.3 of Circular 103/2014, in the case of a foreign contractor receiving compensation which is higher than the compensation payable, the contractor can select to pay foreign contractor tax (FCT) at the appropriate percentage on the receipt, or pay the normal corporate income tax (CIT) rate (20%) on revenue minus expenses. \n“Điều 13. Thuế thu nhập doanh nghiệp \n3. Thuế TNDN đối với khoản tiền bồi thường thu được từ bên đối tác vi phạm hợp đồng đối với trường hợp khoản thu bồi thường lớn hơn giá trị thiệt hại, có thu nhập chịu thuế: Đối với khoản thu nhập từ tiền bồi thường thiệt hại thu được, nhà thầu nước ngoài được lựa chọn khai nộp thuế TNDN theo tỷ lệ thuế TNDN tính trên doanh thu tính thuế hoặc trên cơ sở kê khai doanh thu, chi phí với thuế suất là thuế suất phổ thông.”"
