        question: "38. TCD Co, an Australian company, signed a contract with HMC Co, a Vietnamese company, for TCD Co to provide consultancy skills training for HMC Co's staff in 2025. The value of the training agreement was USD100,000, gross of corporate income tax (CIT) and net of the value added tax (VAT) portion of foreign contractor tax (FCT). The contract value was made up of online courses (20%), whilst the remaining 80% was attributable to training courses which took place in Vietnam. HMC Co settled the contract value in full in 2025.\n<b>What is the amount (in USD), net of foreign contractor tax (FCT), TCD Co can receive from HMC Co in respect of the above training agreement during the year 2025?</b>",
