        section: "Part D",
        type: "standard",
        question: "39. XAL Co is a foreign airline which has an office in Vietnam to sell airfares. In the fourth quarter of 2025, XAL Co earned gross revenue, i.e. before the deduction of any charges or refunds, of USD250,000, based on receipts and records. Of this amount, USD200,000 was for passenger transportation, and the remaining amount related to cargo transportation. Airport charges of USD5,000 were collected from these fares on behalf of the domestic airports. XAL Co also paid refunds of USD7,000 to passengers who returned their fares during the quarter.\n<b>What is the total amount of taxable income (in USD) which XAL Co should declare for the corporate income tax (CIT) portion of the foreign contractor tax (FCT) in the fourth quarter of 2025?</b>",
