        explanation: "First tax year (12-month period from his arrival): 137 days + 45 days = 182 days < 183 days: non-resident\nSecond tax year (calendar year 2026): 45 + 135 = 180 days < 183 days: non-resident\nTutorial note: A tax resident is a person with a presence in Vietnam of 183 days or more in a tax year (excluding the year of arrival which counts the first 12 months rather than the tax year)."
