        question: "On 1 April 2025, Mr Alib, a non-tax resident individual in Vietnam, purchased 200,000 shares of a company listed on the Vietnamese stock market for VND50,000 per share.\nOn 1 December 2025, he sold 60% of the shares for VND30,000 per share (making a loss of VND20,000 per share).\nOn 31 December 2025, he received a dividend of VND8,000 per share on the remaining 80,000 shares held.\n<b>In respect of the transactions described, what is the total amount of personal income tax payable by Mr Alib (in VND million, rounded to one decimal) in the year 2025?</b>",
