        type: "standard",
        question: "Ms Hen Thi is a Vietnamese individual investor in real estate. In 2025, she sold the land use right for a 500 square metre piece of land in Hanoi to another Vietnamese individual. The contractual price for the sale was VND20 billion, representing a gain of VND6 billion over the original price paid by Ms Thi when she purchased the land. The price per square metre as determined by the People's Committee for the same area of land at the time of sale was VND60 million.\n<b>What is the amount of personal income tax (PIT) payable (in VND millions) by Ms Hen Thi on the sale of the land use right in 2025?</b>",
