        explanation: "The correct answer is VND 600 million (500 metre * VND 60 million * 2%) \nAccording to Article 17 of Circular 92/2015 revising Article 12 of Circular 111/2013, If the contractual price of the sale of real estate is lower than the People's Committee price, the taxable gain shall be based on the latter.\nSales of real estate by Individuals are subject to personal Income tax (PIT) at 2% on proceeds (not 20% on the gain)."
