        question: "Mr Alaf, an Oman citizen, arrived in Vietnam to work for VFF Co from 15 April 2024. He completed his employment on 15 November 2025 and left Vietnam. Throughout the period from 15 April 2024 to 15 November 2025 he spent the following number of days in Vietnam:\n- From 15 April 2024 to 31 December 2024 – 126 days\n- From 1 January 2025 to 14 April 2025 – 57 days\n- From 15 April 2025 to 15 November 2025 – 180 days\n<b>What is Mr Alaf's tax residency status for both his first and second tax years in Vietnam, based on the above information?</b>",
