        explanation: "An expat is a resident if he/she spends 183 days or more In Vietnam In the tax year. The first tax year is 12 consecutive months from his/her first arrival, and the second tax year is the subsequent calendar year.\nFirst tax year: 15 April 2025 to 14 April 2026: (126 + 57) = 183 days => resident.\nSecond tax year: 1 January to 15 November 2026: (57 + 180) = 237 days => resident."
