        question: "Ms. Mai Nguyen is a real estate trader and owns various plots of land. In 2011, she bought the land use right for a 1,500 square meter plot of land in Da Nang for VND 3 million per square meter. There was no construction project on the land. In 2025, she sold the land use right under a contract that denominated the proceeds at VND 4 million per square meter. The price of the same area of land set by The People's Committee was VND 2.5 million per square meter in 2010, and VND 10 million per square meter in 2025.\n<b>What is the personal income tax (PIT) liability of Ms. Mai Nguyen from the sale of the land use right in the fiscal year 2025?</b>",
